#include <stdio.h>
#include <string.h>

static int check(const char *s) {
	static const unsigned char enc[] = {
		0x32, 0x3f, 0x36, 0x37, 0x21, 0x28, 0x3f, 0x05, 0x35, 0x31, 0x27
	}; /* "helm{re_ok}" ^ 0x5a */
	size_t n = sizeof(enc);
	if (strlen(s) != n) return 0;
	for (size_t i = 0; i < n; i++) {
		if (((unsigned char)s[i] ^ 0x5a) != enc[i]) return 0;
	}
	return 1;
}

